import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/02-heure-incorrecte.webp",n="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/03-synchro-critique.webp",i="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/04-caisse-revoquee.webp",c="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/04b-retour-appairage.webp",d="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-02-heure-incorrecte.webp",l="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-02b-heure-incorrecte-feuille.webp",u="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-03-synchro-critique.webp",p="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-03b-synchro-critique-feuille.webp",h="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-04-caisse-revoquee.webp",m="/VendoraSystem-docs/captures/2026-11-09-synchro-horloge-retention/android-04b-retour-appairage.webp",A=JSON.parse('{"title":"Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-09-synchro-horloge-retention.md","filePath":"generated/preuves/2026-11-09-synchro-horloge-retention.md","lastUpdated":null}'),g={name:"preuves/2026-11-09-synchro-horloge-retention.md"};function v(y,e,b,_,f,S){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="synchronisation-horloge-decalee-retention-locale-caisse-revoquee-09-11-2026" tabindex="-1">Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026) <a class="header-anchor" href="#synchronisation-horloge-decalee-retention-locale-caisse-revoquee-09-11-2026" aria-label="Permalink to &quot;Synchronisation : horloge décalée, rétention locale, caisse révoquée (09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-09-synchro-horloge-retention</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Synchronisation : horloge décalée, rétention locale, retour à l&#39;appairage d&#39;une caisse révoquée ». Spec 10 RG-SYNC-07 / 20 / 21 et §4.1 ; spec 01 RG-AUTH-14/26 ; spec 04 RG-CASH-28.</p><p><strong>Captures non faites (09/11 au soir)</strong> : le Mac a atteint la limite de processus par utilisateur (2 624 / 2 666, dont ~1 260 processus zombies des deux émulateurs Android de l&#39;utilisateur) — <code>fork failed</code> partout, un simulateur de plus était impossible à démarrer. Le simulateur dédié « Horloge-iPad » avait été appairé à la vraie pile (serveur du worktree sur 8094, base <code>pos_horloge</code>, « Épicerie Lumière (démo) ») avant la panne ; tout a été arrêté ensuite. Le comportement est prouvé par les tests (shared, Android, iOS, serveur). Les pages d&#39;aide n&#39;ont pas encore les images (texte seul) : à ajouter dans <code>help/public/captures/depannage/caisse-ne-synchronise-plus/</code>.</p><h2 id="ios-simulateur-iphone-16-dedie-«-horloge-iphone-»-ios-26-2-10-11-2026" tabindex="-1">iOS (simulateur iPhone 16 dédié « Horloge-iPhone », iOS 26.2, 10/11/2026) <a class="header-anchor" href="#ios-simulateur-iphone-16-dedie-«-horloge-iphone-»-ios-26-2-10-11-2026" aria-label="Permalink to &quot;iOS (simulateur iPhone 16 dédié « Horloge-iPhone », iOS 26.2, 10/11/2026)&quot;">​</a></h2><p>Vraie stack : serveur de dev <code>localhost:8080</code> (main du 10/11), app iOS construite depuis main (avec le correctif <code>shared</code> du miroir), commerce fictif « Épicerie Lumière (démo) », appairé comme caisse « Caisse iPhone (démo) », Nora (caisse) connectée, session non ouverte. Montage sans réglage de dev dans le produit : proxy de test (<code>scratchpad/cap0911/proxy-horloge.py 8095 http://localhost:8080 720000</code>) qui relaie le serveur et décale l&#39;en-tête <code>X-Server-Time</code> de +12 min ; l&#39;app pointe sur <code>http://localhost:8095</code> (<code>defaults write tn.pos.app server.url …</code>). Gestes par le pilote XCUITest (<code>help/tools/mobile/pilote-ios/pi.py</code>), barre d&#39;état 09:41, annotations <code>annotate.py</code>. Simulateur supprimé ensuite.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+s+'" alt=""></td><td>Écran de vente : bandeau « Heure de l&#39;appareil incorrecte : en retard de 12 min sur le serveur. Corrigez la date et l&#39;heure dans les réglages de l&#39;appareil. La vente continue. » (1), pastille <strong>Attention</strong> (2).</td></tr><tr><td><img src="'+n+'" alt=""></td><td>App arrêtée, <code>sync_state.last_pull_at</code> reculé de 22 jours dans <code>pos.db</code> du simulateur, proxy arrêté (serveur injoignable), relance, pastille touchée : feuille Synchronisation « Attention » (1), <strong>« Hors ligne — Dernière synchronisation il y a 22 jours »</strong> (2), « Synchronisation critique : 22 jours sans synchronisation… » (3) ; l&#39;avertissement d&#39;horloge du dernier échange reste affiché dessous.</td></tr><tr><td><img src="'+i+'" alt=""></td><td>Proxy relancé (sans décalage), caisse révoquée par <code>POST /api/v1/devices/{id}/revoke</code>, « Synchroniser maintenant » : écran plein <strong>Caisse révoquée</strong> (1), <strong>Revenir à l&#39;appairage</strong> (2).</td></tr><tr><td><img src="'+c+'" alt=""></td><td>Après « Revenir à l&#39;appairage » : écran <strong>Appairer cet appareil</strong> (1).</td></tr></tbody></table><h2 id="android-tablette-emulator-5554-10-11-2026" tabindex="-1">Android (tablette <code>emulator-5554</code>, 10/11/2026) <a class="header-anchor" href="#android-tablette-emulator-5554-10-11-2026" aria-label="Permalink to &quot;Android (tablette `emulator-5554`, 10/11/2026)&quot;">​</a></h2><p>Vraie stack : serveur de dev <code>localhost:8080</code> (main du 10/11, migrations jusqu&#39;à V95), app debug de main sur la tablette Android <code>emulator-5554</code> (AVD Kds_Tablet, 1600 × 1000, paysage) appairée comme « Caisse tablette (démo) » du commerce fictif « Le Petit Bistrot (démo) », session de caisse n° 1 ouverte. Gestes par <code>adb</code> (pilote <code>drv.py</code> du scratchpad), annotations par <code>help/tools/mobile/annotate.py</code> (cadres en pixels, échelle 1), WebP 1400 px. Camille (caisse) connectée.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+d+'" alt=""></td><td>Heure de la tablette <strong>avancée de 12 min</strong> (<code>settings put global auto_time 0</code>, <code>cmd alarm set-time</code>), reconnexion : au pull suivant, bandeau orange « Heure de l&#39;appareil incorrecte : en avance de 12 min sur le serveur. Corrigez la date et l&#39;heure dans les réglages de l&#39;appareil. La vente continue. » (1) et pastille <strong>Attention</strong> (2). Heure automatique remise ensuite.</td></tr><tr><td><img src="'+l+'" alt=""></td><td>Pastille touchée : feuille <strong>Synchronisation</strong> avec la pastille « Attention » (1) et l&#39;avertissement (2) (<code>synchro-attention</code>).</td></tr><tr><td><img src="'+u+'" alt=""></td><td><code>sync_state.last_pull_at</code> reculé de <strong>22 jours</strong> (app arrêtée, <code>pos.db</code> relue par <code>run-as</code>, modifiée par <code>sqlite3</code> sur le Mac, réécrite), <strong>mode avion</strong>, relance : bandeaux rouges « Dernière synchronisation il y a plus de 72 h — PIN manager en mode dégradé » et « Synchronisation critique : 22 jours sans synchronisation. Reconnectez la caisse à internet au plus vite et prévenez un responsable. La vente continue, rien n&#39;est effacé. » (1), pastille « Attention » (2). Mode avion coupé ensuite : « À jour » au pull suivant, alerte « Caisse non synchronisée » close (« Synchronisation rétablie »).</td></tr><tr><td><img src="'+p+'" alt=""></td><td>Feuille Synchronisation au niveau critique (1). <strong>Défaut constaté (2)</strong> : « Jamais synchronisé » — après un lancement hors ligne, la ligne lit l&#39;état du pull en mémoire (aucun depuis le lancement) au lieu du dernier pull enregistré (<code>sync_state.last_pull_at</code>). Même logique sur iOS (<code>CatalogViewModel.syncStatus</code> initial <code>offline(nil)</code>). Non corrigé ici (correctif iOS + Android à tester sur simulateur) : signalé au rapport.</td></tr></tbody></table><p>Défauts trouvés en chemin et <strong>corrigés</strong> (même lot, commit <code>shared</code> / <code>androidApp</code>) :</p><ul><li>L&#39;alerte des responsables « Caisse non synchronisée » était créée <strong>deux fois</strong> (deux appels simultanés au démarrage : lecture « aucune alerte ouverte » puis insertion, sans transaction) → <code>SyncHealthRepository.refreshManagerAlert</code> lit et écrit dans une seule transaction.</li><li>Cette alerte (titre, résumé, « Synchronisation rétablie ») restait <strong>en français</strong> sur une caisse en anglais ou en arabe → traduite par <code>managerAlertTitle</code> / <code>managerAlertBody</code> / <code>managerAlertResolution</code> (preuves avant / après dans <code>2026-11-09-textes-serveur-restants</code>).</li></ul><p>Captures reprises dans le centre d&#39;aide (FR / EN / AR) : <em>Dépannage › Une caisse ne se synchronise plus</em> (<code>help/public/captures/depannage/caisse-ne-synchronise-plus/02-heure-incorrecte.webp</code>, <code>03-synchro-critique.webp</code>).</p><h3 id="caisse-revoquee-telephone-emulator-5556-10-11-2026" tabindex="-1">Caisse révoquée (téléphone <code>emulator-5556</code>, 10/11/2026) <a class="header-anchor" href="#caisse-revoquee-telephone-emulator-5556-10-11-2026" aria-label="Permalink to &quot;Caisse révoquée (téléphone `emulator-5556`, 10/11/2026)&quot;">​</a></h3><p>Téléphone Android (AVD Medium_Phone_API_36.1, 1080 × 2400), app de main réinstallée à neuf, appairé <strong>exprès</strong> comme caisse « Caisse téléphone (démo) » du commerce fictif « Épicerie Lumière (démo) », Nora (caisse) connectée. Révocation par l&#39;API du back-office (<code>POST /api/v1/devices/{id}/revoke</code>, motif « Téléphone remplacé (démo) » — même appel que <em>Réglages › Appareils › Révoquer</em>), puis « Synchroniser maintenant » dans la feuille Synchronisation.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+h+'" alt=""></td><td>Écran plein <strong>Caisse révoquée</strong> : « Cette caisse a été révoquée au back-office : le serveur n&#39;accepte plus ses envois. Pour vendre à nouveau sur cet appareil, appairez-le avec un nouveau code créé au back-office. » (1), bouton <strong>Revenir à l&#39;appairage</strong> (2). Aucun événement en attente, donc pas de « Réessayer l&#39;envoi ».</td></tr><tr><td><img src="'+m+'" alt=""></td><td>Après <strong>Revenir à l&#39;appairage</strong> : écran <strong>Appairer cet appareil</strong> (1), prêt pour un nouveau code.</td></tr></tbody></table><p>Capture reprise dans le centre d&#39;aide (FR / EN / AR), étape « Caisse révoquée : revenez à l&#39;appairage » : <code>help/public/captures/depannage/caisse-ne-synchronise-plus/04-caisse-revoquee.webp</code>.</p></div>',3)])])}const C=t(g,[["render",v]]);export{A as __pageData,C as default};
